import React, { useState } from 'react';
import { Box, Typography, Container } from '@mui/material';
import { useTranslation } from 'react-i18next';

// The version shown on /mobile-app. Change this one line for the next release.
export const APP_VERSION = '1.07';

const C = {
    night: '#0B1130',
    night2: '#141E48',
    gold: '#E2C15A',
    gold2: '#F3DC8E',
    goldInk: '#8A6510',
    paper: '#FFFDF8',
    ivory: '#F7F1E3',
    muted: '#5D6478',
    line: '#EADFC2',
};
const SERIF = '"Marcellus", "Amiri", Georgia, serif';

// Shipped releases, newest last. Only features that are on in production.
// Words live in src/locales/<lang>/mobileApp.json (releases.items, same order);
// `soon` lists feature indexes still behind a flag.
const RELEASES = [
    { version: '1.04', date: '2026-10-17' },
    { version: '1.05', date: '2026-10-20' },
    { version: '1.06', date: '2026-10-26' },
    { version: '1.07', date: '2026-10-28', soon: [0] },
];
// Built and on its way (coming.items in mobileApp.json), shown as Coming soon until each flag is on in production.

const GOLD_STOPS = (
    <linearGradient id="smGold" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stopColor="#FBE7A6" />
        <stop offset=".45" stopColor="#C99B2E" />
        <stop offset=".7" stopColor="#F3DC8E" />
        <stop offset="1" stopColor="#7A5A12" />
    </linearGradient>
);

// A gold eight-point khatam with the version engraved.
export const VersionSeal = ({ size = 112 }) => {
    const { t, i18n } = useTranslation('mobileApp');
    return (
    <Box component="svg" viewBox="0 0 140 140" role="img" aria-label={t('seal.label', { v: APP_VERSION })}
        sx={{ width: size, height: size, flexShrink: 0, filter: 'drop-shadow(0 6px 20px rgba(226,193,90,.35))' }}>
        <defs>{GOLD_STOPS}</defs>
        <g transform="translate(70 70)">
            <rect x="-50" y="-50" width="100" height="100" fill="url(#smGold)" stroke="#5B420A" strokeWidth="2" />
            <rect x="-50" y="-50" width="100" height="100" fill="url(#smGold)" stroke="#5B420A" strokeWidth="2" transform="rotate(45)" />
            <circle r="44" fill={C.night} stroke={C.gold} strokeWidth="2" />
            <circle r="38" fill="none" stroke={C.gold} strokeWidth=".8" strokeDasharray="2 3" />
            <text y="-10" textAnchor="middle" fontFamily="Georgia, serif" fontWeight="600" fontSize="9" letterSpacing={i18n.dir() === 'rtl' ? 0 : 2.5} fill={C.gold}>{t('seal.word')}</text>
            <text y="20" textAnchor="middle" fontFamily={SERIF} fontSize="30" fill={C.gold2}>{APP_VERSION}</text>
        </g>
    </Box>
    );
};

// The illuminated margin: a layered girih strapwork tile.
const GirihMargin = () => (
    <Box aria-hidden sx={{ position: 'relative', bgcolor: C.night2, minHeight: { xs: 64, md: 'auto' } }}>
        <Box component="svg" sx={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }}>
            <defs>
                <pattern id="smGirih" width="96" height="96" patternUnits="userSpaceOnUse">
                    <rect width="96" height="96" fill={C.night2} />
                    <g fill="none" strokeLinejoin="round">
                        <path d="M48 6 60 30 86 34 66 52 72 80 48 66 24 80 30 52 10 34 36 30Z" stroke={C.goldInk} strokeWidth="7" />
                        <path d="M48 6 60 30 86 34 66 52 72 80 48 66 24 80 30 52 10 34 36 30Z" stroke={C.gold} strokeWidth="4" />
                        <path d="M48 6 60 30 86 34 66 52 72 80 48 66 24 80 30 52 10 34 36 30Z" stroke="#FFF3C9" strokeWidth=".8" />
                        <path d="M0 0 10 34M96 0 86 34M0 96 24 80M96 96 72 80M48 66 48 96" stroke={C.gold} strokeWidth="3" />
                        <circle cx="48" cy="44" r="9" fill="#23407A" stroke={C.gold} strokeWidth="2.5" />
                        <circle cx="48" cy="44" r="3" fill={C.gold2} />
                    </g>
                </pattern>
            </defs>
            <rect width="100%" height="100%" fill="url(#smGirih)" />
        </Box>
    </Box>
);

const Crescent = ({ size = 12 }) => (
    <Box component="svg" viewBox="0 0 24 24" aria-hidden sx={{ width: size, height: size }}>
        <path d="M15 3a9 9 0 1 0 6 15.5A7.5 7.5 0 0 1 15 3Z" fill="currentColor" />
    </Box>
);

const reveal = {
    '@supports (animation-timeline: view())': {
        animation: 'smRise linear both',
        animationTimeline: 'view()',
        animationRange: 'entry 0% entry 40%',
    },
    '@media (prefers-reduced-motion: reduce)': { animation: 'none !important' },
};

export const ReleaseScroll = () => {
    const { t, i18n } = useTranslation('mobileApp');
    const [current, setCurrent] = useState(0);
    const items = t('releases.items', { returnObjects: true });
    const fmt = (iso, opts) => new Intl.DateTimeFormat(i18n.resolvedLanguage || 'en', { timeZone: 'UTC', ...opts }).format(new Date(iso));
    const r = { ...RELEASES[current], ...items[current] };
    return (
        <Box component="section" id="releases" sx={{ bgcolor: C.ivory, py: { xs: 9, md: 12 } }}>
            <Container maxWidth="lg">
                <Box sx={{ textAlign: 'center', mb: 5 }}>
                    <Typography sx={{ fontSize: 13, fontWeight: 600, letterSpacing: '.22em', 'html[dir="rtl"] &': { letterSpacing: 0 }, textTransform: 'uppercase', color: C.goldInk, mb: 1.5 }}>
                        {t('releases.kicker', { v: APP_VERSION })}
                    </Typography>
                    <Typography component="h2" sx={{ fontFamily: SERIF, fontSize: { xs: 32, sm: 40, md: 46 }, lineHeight: 1.12, color: C.night2 }}>
                        {t('releases.h2')}
                    </Typography>
                    <Box role="tablist" aria-label={t('releases.tabs')} sx={{ display: 'flex', justifyContent: 'center', flexWrap: 'wrap', gap: 1, mt: 3 }}>
                        {RELEASES.map((rel, i) => (
                            <Box key={rel.version} component="button" type="button" role="tab" aria-selected={i === current}
                                aria-controls="release-leaf" onClick={() => setCurrent(i)}
                                sx={{
                                    minHeight: 44, px: 2.2, borderRadius: 99, cursor: 'pointer', font: 'inherit', fontSize: 14, fontWeight: 600, letterSpacing: '.06em', 'html[dir="rtl"] &': { letterSpacing: 0 },
                                    border: `1px solid ${i === current ? C.night2 : '#D9C38A'}`,
                                    bgcolor: i === current ? C.night2 : 'transparent', color: i === current ? C.gold : C.goldInk,
                                    '&:focus-visible': { outline: `2px solid ${C.gold}`, outlineOffset: 3 },
                                }}>
                                {rel.version} · {fmt(rel.date, { day: 'numeric', month: 'long' })}
                            </Box>
                        ))}
                    </Box>
                </Box>

                <Box id="release-leaf" role="tabpanel" component="article" sx={{
                    display: 'grid', gridTemplateColumns: { xs: '1fr', md: '96px 1fr' }, overflow: 'hidden',
                    bgcolor: C.paper, borderRadius: '6px', boxShadow: `0 1px 0 #E6D8B4, 0 24px 60px -30px rgba(26,35,64,.35)`, ...reveal,
                }}>
                    <GirihMargin />
                    <Box sx={{ px: { xs: 2.5, md: 6 }, pt: 5, pb: 5.5, minWidth: 0 }}>
                        <Box sx={{ display: 'flex', alignItems: 'baseline', flexWrap: 'wrap', gap: 2, borderBottom: `1px solid ${C.line}`, pb: 2.2, mb: 3.5 }}>
                            <Typography component="h3" sx={{ fontFamily: SERIF, fontSize: 40, color: C.night2 }}>{r.version}</Typography>
                            <Box component="time" dateTime={r.date} sx={{ fontSize: 13, fontWeight: 600, letterSpacing: '.14em', 'html[dir="rtl"] &': { letterSpacing: 0 }, textTransform: 'uppercase', color: C.goldInk }}>{fmt(r.date, { day: 'numeric', month: 'long', year: 'numeric' })}</Box>
                            <Typography sx={{ flexBasis: '100%', color: C.muted }}>{r.summary}</Typography>
                        </Box>
                        <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: 2.5 }}>
                            {r.features.map((f, fi) => (
                                <Box key={f.title} sx={{ border: `1px solid ${C.line}`, borderRadius: '14px', bgcolor: '#fff', p: 2.5 }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, flexWrap: 'wrap', fontSize: 11, fontWeight: 600, letterSpacing: '.12em', 'html[dir="rtl"] &': { letterSpacing: 0 }, textTransform: 'uppercase', color: C.goldInk, mb: 1 }}>
                                        {f.tag}
                                        {r.soon?.includes(fi) && <SoonBadge />}
                                    </Box>
                                    <Typography component="h4" sx={{ fontFamily: SERIF, fontSize: 20, lineHeight: 1.2, color: C.night2, mb: 0.8 }}>{f.title}</Typography>
                                    <Typography sx={{ fontSize: 15, color: C.muted, lineHeight: 1.55 }}>{f.text}</Typography>
                                </Box>
                            ))}
                        </Box>
                        {r.more && <Typography sx={{ mt: 3, fontSize: 15, color: C.muted }}>{r.more}</Typography>}
                    </Box>
                </Box>
            </Container>
        </Box>
    );
};

const SoonBadge = () => {
    const { t } = useTranslation('mobileApp');
    return (
    <Box component="span" sx={{ display: 'inline-flex', alignItems: 'center', gap: 0.7, fontSize: 10.5, fontWeight: 600, letterSpacing: '.14em', 'html[dir="rtl"] &': { letterSpacing: 0 }, textTransform: 'uppercase', color: C.muted, border: '1px solid #C9C3B2', borderRadius: 99, px: 1.1, py: 0.3 }}>
        <Crescent size={10} />{t('coming.badge')}
    </Box>
    );
};

export const ComingSoon = () => {
    const { t } = useTranslation('mobileApp');
    return (
    <Box component="section" id="coming-soon" sx={{ bgcolor: C.paper, py: { xs: 9, md: 12 } }}>
        <Container maxWidth="lg">
            <Box sx={{ textAlign: 'center', maxWidth: 760, mx: 'auto', mb: 5 }}>
                <Typography sx={{ fontSize: 13, fontWeight: 600, letterSpacing: '.22em', 'html[dir="rtl"] &': { letterSpacing: 0 }, textTransform: 'uppercase', color: C.goldInk, mb: 1.5 }}>{t('coming.eyebrow')}</Typography>
                <Typography component="h2" sx={{ fontFamily: SERIF, fontSize: { xs: 32, sm: 40, md: 46 }, lineHeight: 1.12, color: C.night2 }}>{t('coming.h2')}</Typography>
                <Typography sx={{ fontSize: 18, color: C.muted, mt: 2 }}>{t('coming.lede')}</Typography>
            </Box>
            <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: 2.5 }}>
                {t('coming.items', { returnObjects: true }).map((f) => (
                    <Box key={f.title} sx={{ border: `1px dashed #D9C38A`, borderRadius: '14px', p: 2.5, ...reveal }}>
                        <Box sx={{ mb: 1.4 }}><SoonBadge /></Box>
                        <Typography component="h3" sx={{ fontFamily: SERIF, fontSize: 20, color: C.night2, mb: 0.6 }}>{f.title}</Typography>
                        <Typography sx={{ fontSize: 15, color: C.muted, lineHeight: 1.55 }}>{f.text}</Typography>
                    </Box>
                ))}
            </Box>
        </Container>
    </Box>
    );
};
